class LamportClock:
    def __init__(self):
        self.t = 0

    def local_or_send(self):
        self.t += 1          # IR1
        return self.t        # attach to outgoing message on send

    def receive(self, t_msg):
        self.t = max(self.t, t_msg) + 1   # IR2(b)
        return self.t

class VectorClock:
    def __init__(self, i, n):
        self.i, self.T = i, [0] * n

    def local_or_send(self):
        self.T[self.i] += 1
        return list(self.T)        # copy travels with the message

    def receive(self, T_msg):
        self.T = [max(a, b) for a, b in zip(self.T, T_msg)]
        self.T[self.i] += 1
        return list(self.T)

