def send_or_local(pt):
    global l, c
    l_old = l
    l = max(l_old, pt)
    c = c + 1 if l == l_old else 0
    return (l, c)

def receive(lm, cm, pt):
    global l, c
    l_old = l
    l = max(l_old, lm, pt)
    if l == l_old == lm:
        c = max(c, cm) + 1
    elif l == l_old:
        c = c + 1
    elif l == lm:
        c = cm + 1
    else:
        c = 0
