// Simplified from cockroachdb/cockroach pkg/util/hlc/hlc.go
type Timestamp struct {
    WallTime int64 // nanoseconds since the Unix epoch
    Logical  int32 // orders events with equal WallTime
}

// Now: timestamp for a local event or an outgoing request.
func (c *Clock) Now() Timestamp {
    pt := c.physicalNow()
    if c.ts.WallTime >= pt {
        c.ts.Logical++ // wall time is ahead, so the logical clock ticks
    } else {
        c.ts.WallTime, c.ts.Logical = pt, 0
    }
    return c.ts
}

// Update: fold in a timestamp received from another node.
func (c *Clock) Update(rt Timestamp) {
    if rt.WallTime > c.ts.WallTime {
        c.ts = rt
    } else if rt.WallTime == c.ts.WallTime && rt.Logical > c.ts.Logical {
        c.ts.Logical = rt.Logical
    }
}
